$statusNames=['pending'=>'Vorgemerkt','sending'=>'Versand läuft – Ergebnis ausstehend','sent'=>'Versendet','uncertain'=>'Versandergebnis prüfen','skipped'=>'Übersprungen'];
?>
<div class="page-heading"><div><h1>Beitragsmails & Zahlungserinnerungen</h1><p>Jahresbeiträge und offene Zahlungen im Blick</p></div></div>
<div class="content"><section class="card"><h2>Versandrhythmus</h2><p>Am <strong>1. Januar</strong> werden die Beiträge für das neue Kalenderjahr vorbereitet. Zahlungserinnerungen betreffen offene Beiträge des laufenden Jahres und folgen frühestens nach dem Zahlungsziel, mit mindestens <strong>30 Tagen Abstand</strong>.</p><p>Neue Mitglieder haben <strong>einen Kalendermonat ab Rechnungsdatum</strong> Zeit. Familienangehörige ohne eigene Beitragspflicht erhalten keine zusätzliche Rechnung oder Beitragserinnerung.</p><p class="notice">Der tägliche Serverlauf verarbeitet fällige Beiträge und vorgemerkte Nachrichten. Fehlende Rechnungsangaben müssen vorher ergänzt werden.</p></section>
<section class="card"><div class="section-heading"><div><h2>Prüfung für <?= e(dateDe($schedule['today'])) ?></h2><p><?= count($schedule['annual_candidates']) ?> Jahresbeiträge · <?= count($schedule['reminders']) ?> fällige Erinnerungen</p></div><?php if($finance->canWrite()): ?><form method="post" data-confirm="Den heutigen Beitragslauf vorbereiten? Es werden nur fällige Vorgänge vorgemerkt; lokal wird keine E-Mail versendet."><?= csrf().hidden('action','contribution-run') ?><button class="btn btn-solid theme-primary">Heutigen Lauf vorbereiten</button></form><?php endif ?></div>
<?php if(!$schedule['annual_due']): ?><p class="muted">Der nächste jährliche Beitragslauf ist am 1. Januar. Aufnahmebeiträge entstehen gesondert bei der bestätigten Aufnahme.</p><?php endif ?>
<?php if($schedule['annual_candidates']): ?><h3>Jahresbeiträge</h3><div class="table-scroll"><table class="table"><thead><tr><th>Beitragszahler</th><th>Beitragsjahr</th><th>Betrag</th></tr></thead><tbody><?php foreach($schedule['annual_candidates'] as $row): ?><tr><td><?= e($row['name']) ?></td><td><?= (int)$row['year'] ?></td><td><?= e(euro((int)$row['amount_cents'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<h3>Fällige Zahlungserinnerungen</h3><div class="table-scroll"><table class="table"><thead><tr><th>Beitragszahler</th><th>Fällig seit</th><th>Offener Betrag</th><th>Beleg</th></tr></thead><tbody><?php foreach($schedule['reminders'] as $row): ?><tr><td><?= e($row['name']) ?><small><?= e($row['recipient_email']) ?></small></td><td><?= e(dateDe($row['due_date'])) ?></td><td><?= e(euro((int)$row['remaining_cents'])) ?></td><td><a href="<?= e(url(['view'=>'finance','tab'=>'contributions','entry'=>$row['entry_id']])) ?>">Beitrag öffnen</a></td></tr><?php endforeach;if(!$schedule['reminders']): ?><tr><td colspan="4">Heute ist keine Zahlungserinnerung fällig.</td></tr><?php endif ?></tbody></table></div></section>
<?php if($schedule['blocked']): ?><section class="card"><h2>Zurückgestellte Beiträge</h2><p>Diese Beiträge werden derzeit nicht erinnert, etwa wegen einer laufenden Zahlungsfrist, einer verbuchten Zahlung oder fehlender Rechnungsangaben.</p><div class="table-scroll"><table class="table"><thead><tr><th>Beleg</th><th>Grund</th></tr></thead><tbody><?php foreach($schedule['blocked'] as $row): ?><tr><td><a href="<?= e(url(['view'=>'finance','tab'=>'contributions','entry'=>$row['entry_id']])) ?>">Beitrag öffnen</a></td><td><?= e($row['reason']) ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
<section class="card"><h2>Vorgemerkte und versendete Beitragsmails</h2><div class="table-scroll"><table class="table"><thead><tr><th>Beitragsjahr</th><th>Nachricht</th><th>Empfänger</th><th>Status</th></tr></thead><tbody><?php foreach($schedule['deliveries'] as $row): ?><tr><td><?= (int)$row['year'] ?></td><td><?= $row['type']==='invoice'?'Jahresbeitragsrechnung':'Zahlungserinnerung' ?><small><a href="<?= e(url(['view'=>'finance','tab'=>'contributions','entry'=>$row['entry_id']])) ?>">Beitrag öffnen</a></small></td><td><?= e($row['recipient_email']) ?></td><td><?= e($statusNames[$row['status']]??$row['status']) ?><?php if($row['reason']): ?><small><?= e($row['reason']) ?></small><?php endif ?></td></tr><?php endforeach;if(!$schedule['deliveries']): ?><tr><td colspan="4">Noch keine Beitragsmails vorgemerkt.</td></tr><?php endif ?></tbody></table></div></section></div>
